DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _p AS SELECT DISTINCT po.* FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE4 %', (SELECT jsonb_build_object('jobs_min',(SELECT min(created_at)::date FROM jobs),'jobs_n',(SELECT count(*) FROM jobs),'po_job',(SELECT count(*) FROM purchase_orders WHERE job_id IS NOT NULL),'po_nojob',(SELECT count(*) FROM purchase_orders WHERE job_id IS NULL))::text); END $$;
